{
  "name": "@vheins/opencode-model-fallback",
  "publishConfig": {
    "access": "public"
  },
  "version": "0.1.18",
  "description": "OpenCode plugin for automatic model fallback on provider errors",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "require": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsc",
    "prepublishOnly": "tsc",
    "dev": "tsc --watch"
  },
  "keywords": [
    "opencode",
    "plugin",
    "model",
    "fallback",
    "ai",
    "llm"
  ],
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.0.0"
  },
  "dependencies": {
    "@opencode-ai/sdk": "^1.17.0"
  },
  "devDependencies": {
    "@ai-sdk/provider": "^3.0.0",
    "@opencode-ai/plugin": "^1.17.0",
    "typescript": "^5.6.0"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/vheins/opencode-model-fallback.git"
  }
}
